INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('Artists of Rokeby Summer Camp', 'Rokeby Museum', 'https://rokeby.org/event/rokeby-summer-camp-artists-of-rokeby-2026-session-1/', 'https://rokeby.org/event/rokeby-summer-camp-artists-of-rokeby-2026-session-1/', 'jahl@rokeby.org', '802.877.3406', '4334 Route 7', 'Ferrisburgh', 'VT', '05456', 'Vermont', 'day', ARRAY['arts']::text[], ARRAY['nature']::text[], ARRAY['Sketching, scrapbooks and painting','Nature walks','Birdwatching','Animal tracking','History games','Final-day exhibition and pizza party']::text[], NULL, 9, 13, NULL, NULL, 'A 5-day art, nature and history day camp at Rokeby Museum, a historic farm site in Ferrisburgh, for ages 9 to 13. Campers study the Robinson family''s sketches and paintings, take nature walks, birdwatch and track animals, then show their work on the last day. 9:00 am to 3:00 pm; bring lunch, snacks provided.', NULL, NULL, 350, 350, 350, 'week', NULL, NULL, FALSE, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '3df80f88-1485-5067-8dc6-2966b86d733a', 'artists-of-rokeby-ferrisburgh', ST_GeogFromText('SRID=4326;POINT(-73.2792 44.2031)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://rokeby.org/event/rokeby-summer-camp-artists-of-rokeby-2026-session-1/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Farnsworth', 'Girl Scouts of the Green and White Mountains', 'https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/farnsworth.html', NULL, 'customercare@girlscoutsgwm.org', '888-474-9686', '94 Camp Farnsworth Rd', 'Thetford Center', 'VT', '05075', 'Vermont', 'sleepaway', ARRAY['nature','arts','sports','performing_arts']::text[], NULL, ARRAY['swimming','canoeing','kayaking','paddleboarding','archery','slingshots','campfire cooking','arts and crafts','climbing tower','low ropes/challenge course','hiking','backpacking','horseback riding (off-site)','theater/performance','cooking','leadership (Camp Aide, CIT)']::text[], 'girls', NULL, NULL, 0, NULL, 'Girl Scout overnight camp in Thetford, Vermont, with themed programs from three days to two weeks for Girl Scouts who have finished kindergarten through grade 11. Campers sleep in cabins, tentalows, Adirondacks or platform tents, swim in a pool, canoe on a lake, and choose a focus such as archery, arts, cooking, climbing or leadership (Camp Aide, CIT).', NULL, NULL, 200, 2000, NULL, NULL, NULL, NULL, TRUE, TRUE, 'A $100 deposit is due at registration and cannot be refunded. It is included in the listed session price. The page does not say whether the rest of the fee can be refunded.', 'With advance notice, the kitchen can handle food allergies and other dietary needs. It serves gluten-free and vegetarian options and runs as a nut-aware kitchen. The page does not cover other disability accommodations.', 'Has a pool and a 50-acre lake (Lake Abenaki) with a waterfront. Activities include pool swimming, canoeing, kayaking and paddleboarding. The page does not give swim test or lifeguard details.', NULL, NULL, 2026, '83c70e23-33eb-5ae3-b9d5-edb814743e32', 'camp-farnsworth-thetford-center', ST_GeogFromText('SRID=4326;POINT(-72.2495 43.8367)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/farnsworth.html']::text[], '2026-11-13', '2026-11-13', TRUE),
('Petra Cliffs Day Camps (Classic Multi-Sport Camp & Climb On! Day Camp)', 'Petra Cliffs', 'https://www.petracliffs.com/summat-day-camps', 'https://campscui.active.com/orgs/PetraCliffs4?orglink=camps-registration', 'camps@petracliffs.com', '(802) 657-3872', '105 Briggs St.', 'Burlington', 'VT', '05401', 'Vermont', 'day', ARRAY['sports','nature']::text[], NULL, ARRAY['Indoor rock climbing','Outdoor rock climbing','Challenge course at Bolton Adventure Center','Kayaking','Caving']::text[], NULL, 6, 14, NULL, NULL, 'Adventure day camps from a Burlington climbing gym and mountaineering school, 9 AM to 4 PM with extended care 8 to 9 and 4 to 5. The Classic Multi-Sport Camp (ages 6 to 14, ten weeks) mixes rock climbing, kayaking, caving and challenge courses; Climb On! (ages 10 to 14, two weeks) is small-group outdoor rock climbing with professional guides. $575 per week; scholarships available.', NULL, NULL, 575, 575, 575, 'week', TRUE, NULL, NULL, TRUE, '21 days or more before camp: full refund minus a $25 fee. 8 to 20 days: half refund minus $25. 7 days or fewer: no refund.', NULL, NULL, NULL, NULL, 2027, '8615d239-461e-5e08-8fa7-99e01b899c40', 'petra-cliffs-day-camps-classic-multi-sport-camp-and-climb-on-day-camp-burlington', ST_GeogFromText('SRID=4326;POINT(-73.2121 44.4759)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://www.petracliffs.com/day-camp-faqs','https://www.petracliffs.com/s/2027-Registration-Scholarship-Guide.pdf','https://www.petracliffs.com/summat-day-camps']::text[], '2026-11-13', '2026-11-13', TRUE),
('Smirkus Camp', 'Circus Smirkus', 'https://www.smirkus.org/smirkus-camp/camp-sessions/', 'http://app.campdoc.com/register/circussmirkus/', 'camp@smirkus.org', '802-533-2423', '409 Breezy Ave', 'Greensboro', 'VT', '05841', 'Vermont', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['trapeze','aerials','acrobatics','juggling','clowning','plate spinning','globe walking','act creation and performance','campfires','camp games']::text[], NULL, 5, 18, NULL, NULL, 'Circus arts camp in Greensboro, Vermont, offering a one-day program, overnight sessions and multi-week sleepaway sessions for ages 5-18. Training covers aerials, acrobatics, juggling and clowning, and some advanced sessions require a placement video.', NULL, NULL, 250, 5500, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '40ff42d2-f8ec-5a05-b4d4-5e8c0cb740f0', 'smirkus-camp-greensboro', ST_GeogFromText('SRID=4326;POINT(-72.2848 44.602)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.smirkus.org/smirkus-camp/camp-sessions/']::text[], '2026-11-13', '2026-11-13', TRUE),
('TCC Summer Camp', 'The Community Campus', 'https://www.thecommunitycampus.org/summer-camp/', NULL, NULL, '603-322-1317', '281 Barnard Rd', 'Woodstock', 'VT', '05091', 'Vermont', 'day', ARRAY['nature','sports']::text[], NULL, ARRAY['Hiking','Gardening','Birding','Rock climbing','Themed games','Field trips','Nature exploration']::text[], NULL, 5, 12, NULL, NULL, 'A weekly day camp in Woodstock, VT for ages 5–12. It runs 8am–4pm with optional late care until 5pm. Each week has a theme, such as hiking, plants, birding or unusual sports, and most weeks include field trips.', NULL, NULL, 65, 285, 285, 'week', TRUE, NULL, FALSE, TRUE, 'You must give 30 days'' notice to withdraw. If you cancel within 30 days, you still pay in full for the registered days. Cancellations made earlier than that get at most a 50% refund. From May 15, absences are still charged under the 30-day policy. If enrollment is forfeited for unpaid late fees, no refund is given.', NULL, NULL, NULL, NULL, 2026, '68beec58-22f2-5ac4-9c9f-f185f5a550d2', 'tcc-summer-camp-woodstock', ST_GeogFromText('SRID=4326;POINT(-72.5483 43.5944)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://www.thecommunitycampus.org/summer-camp/','https://www.thecommunitycampus.org/tuition-assistance/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Bethany Birches Camp – Summit (Summit Mid & Summit High)', 'Bethany Birches Camp', 'https://bethanybirches.org/summer-camps-summit/', 'https://bethanybirches.org/register-now/', NULL, '802-672-5220', '2610 Lynds Hill Road', 'Plymouth', 'VT', '05056', 'Vermont', 'sleepaway', ARRAY['outdoor']::text[], NULL, ARRAY['Creek hike','Cardboard boat race','Cooking over the fire','Iron Chef','Coffee House','Barn Party','Capture the flag','Free time']::text[], NULL, 11, 16, NULL, NULL, 'Summit is Bethany Birches Camp''s overnight program for older campers in Plymouth, Vermont, with Sunday to Friday weeks: Summit Mid for ages 11-14 and Summit High for ages 13-16. Campers get more free time, spend time outdoors and cook meals over the fire. Families pick one of five price tiers; the two lowest are for households that qualify by income.', NULL, NULL, 175, 865, NULL, NULL, NULL, NULL, NULL, TRUE, 'A $50 nonrefundable deposit holds a spot and counts toward the total. Full payment is due 3 weeks before the session. Cancel in writing 3 or more weeks ahead and the payment, less the deposit, stays on account for another program within a year. Later cancellations and no-shows get nothing back or forwarded.', NULL, NULL, NULL, NULL, 2026, 'e3a0c97b-f73e-567b-922b-92ae462a9dc8', 'bethany-birches-camp-summit-summit-mid-and-summit-high', ST_GeogFromText('SRID=4326;POINT(-72.6936 43.5088)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://bethanybirches.org/contact-us/','https://bethanybirches.org/kids-to-camp/','https://bethanybirches.org/register-now/','https://bethanybirches.org/summer-camps-summit/','https://bethanybirches.org/summer-camps/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Akeela', NULL, 'https://campakeela.com/', NULL, NULL, '802-333-4843', '1 Thoreau Way', 'Thetford Center', 'VT', '05075', 'Vermont', 'sleepaway', ARRAY['special_needs','general']::text[], NULL, ARRAY['Art','Ceramics','Cooking','Dance','Drama','Music','Rocketry','Woodshop','Canoeing','Kayaking','Sailing','Stand-up paddleboarding','Swim instruction','Archery','Basketball','Frisbee golf','Martial arts','Soccer','Softball','Tennis','Ropes courses and climbing wall','Farm and garden','Animal care','Day hikes','Overnight camping trips','Dungeons & Dragons','Campfires']::text[], NULL, 9, 17, NULL, NULL, 'Overnight camp for neurodivergent kids who have finished grades 3 to 10 (ages 9 to 17), on Miller Pond near Thetford Center, Vermont. Campers do a traditional camp program while staff coach social skills. Two three-week sessions in 2027; tuition is all-inclusive apart from baggage shipping and the optional ride home, and includes a one-way bus to camp.', NULL, NULL, 9900, 9900, NULL, NULL, NULL, TRUE, NULL, TRUE, '$1,000 deposit with the application, refunded if camp or family decides the child won''t attend. Half the balance is due January 31, 2027 and the rest April 30. Without the optional $500 assurance plan, everything is refundable less a $250 fee until January 31; after that cancellation fees rise from $2,500 to $6,000, and nothing is refunded from June 1. The assurance plan gives a fuller refund up to May 1 and partial credit after.', 'Built for neurodivergent campers, many with autism (Level 1), ADHD or NLD; no diagnosis is required. Campers must manage daily living with some prompting and live in a cabin of up to 9 campers with 4 counselors. The camp says it is not the right fit for kids who need one-to-one behavioral support or have a history of aggression, running away or recent psychiatric hospitalization. Families and directors decide fit together during the application.', NULL, NULL, NULL, 2027, 'a21bc02c-3815-5131-9c6b-81491c534e14', 'camp-akeela-thetford-center', ST_GeogFromText('SRID=4326;POINT(-72.2495 43.8367)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://campakeela.com/about-us/','https://campakeela.com/about-us/activities-typical-day/','https://campakeela.com/about-us/faqs/','https://campakeela.com/about-us/payment-terms/','https://campakeela.com/dates-and-rates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Sangamon For Boys', NULL, 'https://campsangamon.com/', 'https://campsangamon.com/wp-content/uploads/2026/08/Application-2027.pdf', 'darcey@campsangamon.com', '(802) 665-7505', '382 Camp Lane', 'Pittsford', 'VT', '05763', 'Vermont', 'sleepaway', ARRAY['sports','arts','nature']::text[], NULL, ARRAY['Outdoor pursuits','Aquatics','Farming','Creative arts','Sports']::text[], 'boys', NULL, NULL, NULL, NULL, 'Overnight camp for boys on a 200-acre hill farm with a spring-fed lake in Pittsford, Vermont, near Rutland and Killington. Campers live in cabins and do outdoor pursuits, aquatics, farming, creative arts and sports. In 2027 families book two-, three-, four- or five-week stays between June 27 and August 14.', NULL, NULL, 3595, 8413, NULL, NULL, NULL, NULL, TRUE, TRUE, 'Deposit is $350 with the application, or $500 for early enrollment by December 31, which takes 3% off with the balance due March 1. Otherwise half the balance is due June 1 and the rest on arrival. Siblings get 3% off each child. If camp can''t safely open, everything is refunded. Withdraw after March 15 and before May 1 and all payments beyond the deposit come back; no refunds after May 1.', NULL, NULL, NULL, NULL, 2027, 'cba1b6ea-a730-5b10-b9a8-80eeb95b9f8b', 'camp-sangamon-for-boys-pittsford', ST_GeogFromText('SRID=4326;POINT(-73.0485 43.71)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://campsangamon.com/about-camp-sangamon/','https://campsangamon.com/dates-rates/','https://campsangamon.com/wp-content/uploads/2026/08/Application-2027.pdf','https://campsangamon.com/wp-content/uploads/2026/08/Dates-and-Rates-27.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Hildene Summer Day Camps', 'Hildene, The Lincoln Family Home', 'https://hildene.org/pages/day-camps', NULL, 'lisa@hildene.org', '802-362-1788', '1005 Hildene Road', 'Manchester', 'VT', '05254', 'Vermont', 'day', ARRAY['nature','arts']::text[], NULL, ARRAY['aquatic insect study','farm animal care','gardening and harvesting','goat dairy and cheese making','plant identification and foraging','forest ecology','art (drawing, painting, sculpture, weaving, felting)','carpentry','hikes','crafts','games','stories']::text[], NULL, NULL, NULL, 2, 8, 'Week-long nature, farm and art day camps (9am to 3pm) on the Hildene estate in Manchester, Vermont, for children entering grades 2 to 6, plus a two-week Youth Corps carpentry and farm program for youth entering grades 7 and 8. Members pay less; scholarships are available.', NULL, NULL, 325, 525, 375, 'week', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '982f3144-3886-5ed3-bb35-e4dce4703f6b', 'hildene-summer-day-camps-manchester', ST_GeogFromText('SRID=4326;POINT(-73.0712 43.1623)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://hildene.org/pages/day-camps']::text[], '2026-11-13', '2026-11-13', TRUE),
('Point CounterPoint Youth Sessions', 'Point CounterPoint', 'https://pointcp.com/youth-sessions/', 'https://pointcp.com/youth-sessions/#apply', NULL, '(267) 886-5359', '1361 Hooker Road', 'Leicester', 'VT', '05733', 'Vermont', 'sleepaway', ARRAY['performing_arts']::text[], NULL, ARRAY['Chamber music coachings','Private lessons','Masterclasses','Uncoached rehearsals','Music electives (audition techniques, sight-reading, fiddling)','Music theory and composition workshops','Camp choir','Concerts','Swimming','Soccer','Arts and crafts','Weekly field trips','Canoeing on Lake Dunmore (Fourth of July)']::text[], NULL, 8, 19, NULL, NULL, 'Overnight chamber music camp on Lake Dunmore in Leicester, Vermont, running since 1963. Five 2027 youth sessions, each with its own ages and music director: four two-week sessions for ages 11 to 19 and a one-week Prelude for ages 8 to 13. Days mix coachings, lessons, rehearsals and concerts with swimming, games and weekly trips.', NULL, NULL, 2200, 4400, NULL, NULL, NULL, NULL, NULL, TRUE, 'Once a camper is accepted, a $1,000 enrollment deposit counts toward tuition, and tuition is due in full by June 1. Withdraw by April 30 and half of what you''ve paid comes back; from May 1 all payments are forfeited.', NULL, 'The camp sits on the shore of Lake Dunmore. The daily schedule includes an optional early morning swim and afternoon swimming, and on the Fourth of July campers watch fireworks from canoes on the lake. The site doesn''t describe waterfront supervision.', NULL, NULL, 2027, '4ffe9418-b633-5845-978d-e5d67c504bcb', 'point-counterpoint-youth-sessions-leicester', ST_GeogFromText('SRID=4326;POINT(-73.0997 43.8745)'), FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://pointcp.com/coming-to-camp/','https://pointcp.com/tuition-and-financial-aid/','https://pointcp.com/youth-sessions/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Boys & Girls Club of Burlington Summer Camp', 'Boys & Girls Club of Burlington', 'https://www.bandgclub.org/summercamp', NULL, 'greatfutures@bandgclub.org', '802-864-5263', '62 Oak Street', 'Burlington', 'VT', '05401', 'Vermont', 'day', ARRAY['sports','academic','nature']::text[], NULL, ARRAY['swimming lessons','tennis','outdoor exploration','hands-on learning','summer learning / academic support']::text[], NULL, NULL, NULL, NULL, NULL, 'An eight-week, full-day summer camp from the last week of June through late August, offered as two four-week sessions. Campers get meals and snacks, swimming lessons in the Club pool, tennis, outdoor exploration and help with summer learning plans. The Club says 90% of campers receive full scholarships.', NULL, NULL, NULL, NULL, 50, 'week', NULL, NULL, TRUE, TRUE, NULL, NULL, 'Swimming lessons and water safety in the Club pool. The handbook says each group swims up to twice a day, split between lessons, pool games and free swim, with at least four certified lifeguards on duty.', NULL, NULL, 2026, 'dffff2b9-38df-52db-932a-37c68d8ca086', 'boys-and-girls-club-of-burlington-summer-camp-burlington', ST_GeogFromText('SRID=4326;POINT(-73.2121 44.4759)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://www.bandgclub.org/_files/ugd/7af1b2_1551361a54884b60b2875e44415299d7.pdf','https://www.bandgclub.org/summercamp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Hochelaga', 'YWCA Vermont', 'https://ywcavt.org/camp-hochelaga-about', 'https://ywcavt.org/dates-rates-registration', 'contactus@ywcavt.org', '(802) 372-4510', '34 Hochelaga Rd', 'South Hero', 'VT', '05486', 'Vermont', 'sleepaway', NULL, NULL, ARRAY['Block classes (overnight campers)','Daily activity choices for day campers, such as basketball and paper puppets','Day camp sleepovers (one night per session)','Evening program','Changeover weekend trips: state park hikes, museums, indoor rock climbing, drive-in movies']::text[], 'girls', NULL, NULL, NULL, NULL, 'YWCA Vermont''s inclusive girls+ camp in South Hero. It offers one-week overnight sessions (Sunday to Friday) plus a two-week session, weekly day camp with a free bus from Burlington and Milton, a one-week Mini-Camp that mixes day and overnight, and a 5-week Counselor in Training program. Tuition has three tiers, and the lower two are open to everyone.', NULL, NULL, 450, 2850, NULL, 'session', NULL, TRUE, NULL, TRUE, 'Cancel in writing or by phone at least two weeks before the camper arrives for a refund; less than two weeks before, no refund. The deposit is non-refundable (a Circle of Girls+ scholarship applicant who can no longer accept may get it back). Homesickness is not a reason for a refund.', 'Not a specialized medical or therapeutic camp, but the team includes a camper mental health specialist, and leaders are trained to work with youth with mental health needs, disabilities and learning disabilities. Families of campers with specific needs are asked to reach out first.', NULL, TRUE, 'https://ywcavt.org/camp-hochelaga-about', 2027, 'f7284eb1-b4dd-5d57-8e1a-12061b0bfcab', 'camp-hochelaga-south-hero', ST_GeogFromText('SRID=4326;POINT(-73.3092 44.6271)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://ywcavt.org/camp-hochelaga-about','https://ywcavt.org/dates-rates-registration','https://ywcavt.org/day-camp-1','https://ywcavt.org/who-we-serve']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Ta-Kum-Ta', 'Camp Ta-Kum-Ta', 'https://www.takumta.org/', 'https://takumta.campintouch.com/ui/forms/application/camper/App', 'dina@takumta.org', '802-372-5863', '77 Sunset View Road', 'South Hero', 'VT', '05486', 'Vermont', 'sleepaway', ARRAY['special_needs']::text[], NULL, ARRAY['Swimming','Athletics','Ropes course','Arts & crafts','Rock climbing','Hot-air balloon rides','Formal dances','Cruises on Lake Champlain']::text[], NULL, 7, 17, NULL, NULL, 'A year-round camp in South Hero for children ages 7 to 17 who have or have had cancer and live in or are treated in Vermont (some programs also serve Northern New York). The main program is a one-week overnight summer camp (Sunday to Saturday); there are also winter weekends by age group, a siblings weekend and a camper exchange.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, NULL, NULL, 'For children ages 7-17 who have or have had cancer. Medical staff, many of them the same people who treat campers at the hospital, are at camp 24/7, and camp is about 15 minutes from UVM Medical Center. The FAQ says camp is free for children treated at UVM Medical Center and their families, including transportation from the hospital to summer camp, food, medical care and activities.', NULL, NULL, NULL, 2026, '9a40f013-a84d-53e4-a99e-b099a20de023', 'camp-ta-kum-ta', ST_GeogFromText('SRID=4326;POINT(-73.3092 44.6271)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.takumta.org/','https://www.takumta.org/about-us/directions-to-camp/','https://www.takumta.org/parents/camper-faq/','https://www.takumta.org/parents/register-a-camper/','https://www.takumta.org/programs/camp-ta-kum-tas-summer-program/','https://www.takumta.org/programs/tkt-programs/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Community Sailing Center Youth Camps', 'Lake Champlain Community Sailing Center', 'https://communitysailingcenter.org/youth-camps/', NULL, 'info@communitysailingcenter.org', '(802) 864-2499', '505 Lake Street', 'Burlington', 'VT', '05401', 'Vermont', 'day', ARRAY['sports','nature','STEM']::text[], NULL, ARRAY['Sailing (dinghies and keelboats)','Racing skills','Foiling (Waszp)','Kayaking','Canoeing','Paddleboarding','Yoga','Painting/art','Swimming','Tennis','Lake science/STEM','Pirates of the Champlain camp']::text[], NULL, 6, 16, NULL, NULL, 'Week-long and two-week sailing day camps on Lake Champlain in Burlington, grouped by age and skill level. Some camps combine half a day of sailing with another activity such as yoga, swimming, art, tennis or paddleboarding.', NULL, NULL, 450, 1070, 565, 'week', TRUE, NULL, FALSE, TRUE, NULL, NULL, 'Camps run on Lake Champlain. Campers and staff wear life jackets on docks and boats, and every camper does a short swim assessment on day one; knowing how to swim is not required to sail, but Level II and III need basic swimming proficiency. Water time depends on cyanobacteria; in a bloom campers stay out of the water and sail farther offshore. Swim & Sail campers take swim lessons in the Burlington Tennis Club pool.', NULL, NULL, 2026, 'bee07600-0c2c-5215-8266-4aeffb9cb67a', 'community-sailing-center-youth-camps-burlington', ST_GeogFromText('SRID=4326;POINT(-73.2121 44.4759)'), TRUE, FALSE, FALSE, TRUE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://communitysailingcenter.org/hours-location/','https://communitysailingcenter.org/youth-camp-guide/','https://communitysailingcenter.org/youth-camps/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Hosmer Point Camp', 'Craftsbury Outdoor Center', 'https://www.hosmerpoint.com', 'https://www.hosmerpoint.com/register', 'office@hosmerpointcamp.org', '802-586-2090', '76 Hosmer Point Lane', 'Craftsbury Common', 'VT', '05827', 'Vermont', 'sleepaway', NULL, NULL, NULL, 'coed', 9, 15, 3, 9, 'Overnight camp in Craftsbury Common, Vermont, with four 13-day sleepaway sessions for campers of all genders in grades 3-9 (ages 9-15 for homeschoolers or campers from outside the US). Tuition uses an honor-system sliding scale, and scholarship funds are available with no application.', NULL, NULL, 700, NULL, NULL, 'session', NULL, TRUE, TRUE, TRUE, NULL, 'The camp aims to accommodate campers with medical, behavioral, mental health or developmental conditions when it can keep everyone safe, and asks families to get in touch before registering. Staff are not specifically trained for these needs, and campers are not under direct adult supervision at all times. A registered nurse lives on site.', NULL, NULL, NULL, 2027, '66276030-2a17-5186-8078-d32728c38e1d', 'hosmer-point-camp-craftsbury-common', ST_GeogFromText('SRID=4326;POINT(-72.3894 44.6481)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.hosmerpoint.com/dates','https://www.hosmerpoint.com/faq','https://www.hosmerpoint.com/rates']::text[], '2026-11-13', '2026-11-13', TRUE),
('Montshire Museum of Science Summer Camp', 'Montshire Museum of Science', 'https://montshire.org/programs/for-children-families/summer-camps/', 'https://montshire.campmanagement.com/p/request_for_info_m.php?action=enroll', 'montshire@montshire.org', '(802) 649-2200', '1 Montshire Road', 'Norwich', 'VT', '05055', 'Vermont', 'day', ARRAY['STEM','nature']::text[], NULL, ARRAY['hands-on exploration','experiments','observation','games','water play']::text[], NULL, NULL, NULL, NULL, NULL, 'A science museum day camp running weekly sessions from 9am to 3:30pm. Each week has its own theme and includes hands-on exploration, experiments, observation, games and water play.', NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, TRUE, 'For 2026: cancel on or before June 1 for a full refund minus a $40 administrative fee. Cancel from June 2 up to 3 weeks before the session starts for a 50% refund minus the $40 fee. No refund less than 3 weeks before the session starts. Late pick-up costs $10 per 10 minutes, starting at 3:40.', NULL, NULL, NULL, NULL, 2026, 'a3c88f45-92c6-50a5-bf7b-16f140893bd1', 'montshire-museum-of-science-summer-camp-norwich', ST_GeogFromText('SRID=4326;POINT(-72.324 43.7776)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://montshire.org/programs/for-children-families/summer-camps/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Stowe Rec Summer Camp', 'Town of Stowe Parks & Recreation', 'https://www.stowevt.gov/Departments/Parks-Recreation/Summer-Camp', 'https://secure.rec1.com/VT/stowe-vt/catalog/index/9bbeaf522d0c1fa9119d450692c86a3b?filter=c2VhcmNoPSZjYXRlZ29yeSU1QjMzMjk0JTVEPTE=', 'recreation@stowevt.gov', '(802) 253-7350', NULL, 'Stowe', 'VT', '05672', 'Vermont', 'day', ARRAY['sports','arts','nature','STEM']::text[], NULL, ARRAY['hiking','biking','water activities','sports','arts and expression','science','theme weeks','Friday field trips']::text[], NULL, NULL, NULL, 0, 9, 'A town-run day camp in Stowe, Vermont, for children who have finished kindergarten through 9th grade. It runs Monday to Friday, 7:45am to 4:15pm, with hiking, biking, water activities, camper-choice sports, arts and science, weekly themes and Friday field trips.', NULL, NULL, 255, 1550, 255, 'week', NULL, NULL, NULL, TRUE, 'Cancel more than 30 days ahead: full refund minus a non-refundable $50 registration fee. Cancel 7–30 days ahead: 75% refund. Cancel with less than a week''s notice: no refund.', NULL, NULL, NULL, NULL, 2026, 'a002ec7f-ba5c-5099-987a-c023e222c383', 'stowe-rec-summer-camp-stowe', ST_GeogFromText('SRID=4326;POINT(-72.6868 44.4651)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.stowevt.gov/Departments/Parks-Recreation/Summer-Camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Brattleboro Music Center Summer Programs', 'Brattleboro Music Center', 'https://bmcvt.org/summer-programs/', NULL, 'info@bmcvt.org', '(802) 257-4523', '72 Blanche Moyse Way', 'Brattleboro', 'VT', '05301', 'Vermont', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['singing','dancing','storytelling','singing games']::text[], NULL, 6, 12, NULL, NULL, 'A community music school in Brattleboro, VT, that runs Step it Down, a one-week morning camp of songs, dances, folktales and singing games for children ages 6 to 12. 2027 dates are not posted yet.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '8578dda3-1b52-5f07-91c4-5165e070db88', 'brattleboro-music-center-summer-programs-brattleboro', ST_GeogFromText('SRID=4326;POINT(-72.6331 42.8602)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://bmcvt.org/summer-programs/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Downer', NULL, 'https://campdowner.com', 'https://campdowner.campbrainregistration.com', 'registrar@campdowner.com', '802-763-7007', '1535 Downer Road', 'Sharon', 'VT', '05065', 'Vermont', 'sleepaway', NULL, NULL, NULL, NULL, 8, 16, NULL, NULL, 'Overnight summer camp in Sharon, Vermont for campers ages 8 to 16, with one-week sessions running Sunday to Friday and a two-week CIT II session for ages 11 to 16. Families pick one of three voluntary price tiers, and partial or full scholarships are available.', NULL, NULL, 560, 1540, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '0cb224de-d422-5547-b37d-3f6d58150adb', 'camp-downer-sharon', ST_GeogFromText('SRID=4326;POINT(-72.4352 43.7876)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://campdowner.com/registration/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Lake Champlain Maritime Museum Day Camps', 'Lake Champlain Maritime Museum', 'https://www.lcmm.org/camps/day-camps/', NULL, 'camps@lcmm.org', '802-475-2022', '4472 Basin Harbor Road', 'Vergennes', 'VT', '05491', 'Vermont', 'day', ARRAY['nature','STEM','arts']::text[], NULL, ARRAY['fishing','hiking','canoeing','snorkeling','metalsmithing','swimming','sailing','rowing','kayaking','woodworking','boat building','nautical archaeology']::text[], NULL, 6, 16, NULL, NULL, 'Week-long summer day camps for ages 6–16 run by a museum on Lake Champlain. Each camp is grouped by age and has one theme, such as fishing, watershed ecology, snorkeling, metalsmithing, boating, or building a kayak over three weeks. All tuition is pay-what-you-can.', NULL, NULL, 400, 2950, 400, 'week', NULL, NULL, NULL, TRUE, 'Cancel 14 or more days before the first day of the session for a full refund of the amount paid. After that, you may not get a full refund. Full Camp Participation Policies are on a separate page.', NULL, 'Camps take place on and around Lake Champlain. They include snorkeling (Watershed Ecology and Underwater Exploration), swimming in the lake, and canoeing, kayaking, sailing and rowing in the Museum''s fleet of boats. The page says staff are trained in CPR/First Aid but does not mention lifeguard certification or swim tests.', NULL, NULL, 2026, '74db8706-f8cb-5096-9bc2-a5a8f5457c31', 'lake-champlain-maritime-museum-day-camps-vergennes', ST_GeogFromText('SRID=4326;POINT(-73.2553 44.1677)'), TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://www.lcmm.org/camps/day-camps/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Night Eagle Wilderness Adventures', NULL, 'https://www.nighteaglewilderness.com', 'https://www.nighteaglewilderness.com/dates-and-rates', 'Bruce@nighteaglewilderness.com', '(802) 353-4071', NULL, 'Wallingford', 'VT', '05773', 'Vermont', 'sleepaway', ARRAY['outdoor','adventure']::text[], NULL, ARRAY['survival skills','target sports','waterfront','wilderness trips']::text[], 'boys', 10, 14, NULL, NULL, 'A small, primitive overnight camp for no more than 36 boys ages 10 to 14 near Wallingford, Vermont, where campers live in tipis without electronics. It is built around 3- to 6-week sessions, with 1- and 2-week options for young or new campers.', NULL, NULL, 1335, 5145, NULL, 'session', NULL, NULL, NULL, TRUE, 'If notice of withdrawal reaches the camp office by May 1, tuition is refunded minus a $100 processing fee. After May 1 there are no refunds for withdrawals, session changes, late arrivals or no-shows. The one exception is documented physical illness of the camper, which gets back 50% of unused tuition. If illness or accident cuts a stay short, tuition is refunded pro rata. There is no refund if a camper is sent home for breaking camp rules or is withdrawn voluntarily. If the camp cancels a session, all money is refunded.', NULL, NULL, NULL, NULL, 2027, 'f41a00ab-9f85-5fb2-8868-5095e46cd98d', 'night-eagle-wilderness-adventures-wallingford', ST_GeogFromText('SRID=4326;POINT(-72.966 43.4727)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.nighteaglewilderness.com/','https://www.nighteaglewilderness.com/contact-us','https://www.nighteaglewilderness.com/dates-and-rates']::text[], '2026-11-13', '2026-11-13', TRUE),
('Shelburne Farms Summer Camps', 'Shelburne Farms', 'https://shelburnefarms.org/visit-and-learn/family-youth-programs', 'https://shelburnefarmssummercamp.campbrainregistration.com/Home/Landing', 'registration@shelburnefarms.org', '802-985-8686', '1611 Harbor Road', 'Shelburne', 'VT', '05482', 'Vermont', 'day', ARRAY['nature']::text[], NULL, ARRAY['goat hikes','bread and butter making','wool crafting','fort building','forest games','harvesting','visiting the dairy herd and sheep','cooking over the fire','nature crafts','lake shore exploring','pond exploration']::text[], NULL, 5, 17, NULL, NULL, 'Week-long day camps, 9 am to 3 pm, for ages 5 to 14 on Shelburne Farms, a 1,400-acre working farm and education nonprofit in Shelburne, Vermont, plus a Sunday-to-Wednesday overnight for ages 14 to 17. Campers care for animals, harvest and cook from the gardens, and play in the forest, grouped by age.', NULL, NULL, 325, 800, 325, 'week', TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, 'ac8a923c-1dce-52f9-860b-53564cf4661f', 'shelburne-farms-summer-camps-shelburne', ST_GeogFromText('SRID=4326;POINT(-73.2435 44.3893)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://shelburnefarms.org/node/3376/2026-summer-camp-information','https://shelburnefarms.org/node/3376/2026-summer-camp-information/camp-logistics','https://shelburnefarms.org/sites/default/files/2026-02/2026%20Camps%20by%20Ages%20%285%20-%2017%29%20-%20Flyer%20%281%29%20%281%29.pdf','https://shelburnefarms.org/visit-and-learn/family-youth-programs']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Camp at the Y in BTV', 'Greater Burlington YMCA', 'https://www.gbymca.org/programs/child-care-camps/summer-camps/gbymca-summer-camps/', 'https://operations.daxko.com/Online/3078/ProgramsV2/Search.mvc?keywords=&program_id=CMP21398333&expanded=categories%2Clocations&coming_soon=False&category_ids=CAT2576475&all_categories=false&location_ids=B400&all_locations=false&date_ranges%5B0%5D.start=&date_ranges%5B0%5D.end=&birth_dates=', 'aisrael@gbymca.org', '802-862-9622', '298 College Street', 'Burlington', 'VT', '05401', 'Vermont', 'day', ARRAY['arts','STEM','sports']::text[], NULL, ARRAY['swimming','arts and crafts','STEAM activities','gym games','walking field trips','weekly field trips']::text[], NULL, NULL, 10, NULL, NULL, 'Weekday day camp at the Greater Burlington YMCA for kids who have finished kindergarten, up to age 10. Campers swim in the Y pool, do arts and crafts and STEAM activities, play games in the gym, and go on walking field trips around Burlington.', NULL, NULL, 375, 430, 430, 'week', NULL, NULL, FALSE, TRUE, 'The $30 registration fee and $25 weekly deposits are non-refundable. Cancellations and schedule changes must be made two weeks before camp starts, and full tuition is due May 1. If the Y cancels a whole week, the amount is credited to a later week or refunded; if a scholarship still leaves camp unaffordable and the family cancels, the fee and deposit are refunded.', NULL, 'Campers swim in the YMCA''s indoor pool during the week. The page gives no details on swim testing or supervision.', NULL, NULL, 2026, '00907bd9-cc93-56ee-8039-dc5207f23936', 'summer-camp-at-the-y-in-btv-burlington', ST_GeogFromText('SRID=4326;POINT(-73.2121 44.4759)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=298+College+Street&city=Burlington&state=VT&benchmark=Public_AR_Current&format=json','https://www.gbymca.org/programs/child-care-camps/summer-camps/gbymca-summer-camps/','https://www.gbymca.org/wp-content/uploads/2026/01/2026-Camp-Financial-Policy.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('YMCA Camp Abnaki Day Camp', 'Greater Burlington YMCA', 'https://campabnaki.org/summer-camp-options/day-camp/', 'https://www.ultracamp.com/clientlogin.aspx?idCamp=798&campCode=9rm', 'info@campabnaki.org', '802-652-8180', '1252 Abnaki Road', 'North Hero', 'VT', '05474', 'Vermont', 'day', ARRAY['sports','arts','nature']::text[], NULL, ARRAY['swimming','archery','arts + crafts','small and large group games','volleyball','Gaga Ball','skills classes']::text[], 'boys', NULL, NULL, 0, 4, 'A weekday day camp for boys who have completed kindergarten through grade 4, held at YMCA Camp Abnaki in North Hero, VT. Boys swim, play group games and try activities like archery and arts and crafts, then go home each evening. Lunch, an afternoon snack and a bus from South Burlington are included.', NULL, NULL, 525, 525, 525, 'week', NULL, TRUE, TRUE, TRUE, 'The $100 deposit for each session is non-refundable. Fees paid before the May 1 deadline are refunded, minus the deposit. After May 1, all payments are non-refundable, though the Camp Director may approve a pro-rated refund for a long illness or an accident. Cancellations must be made in writing. Homesickness, head lice and dismissal for behavior do not qualify for a refund.', NULL, 'There is daily waterfront time (free swim or volleyball). Certified lifeguards supervise all aquatic activities. The shore is rocky and has zebra mussels, so sandals or water shoes are strongly recommended.', NULL, NULL, 2027, 'e52c317a-36cf-5082-b18f-4afb1d225061', 'ymca-camp-abnaki-day-camp-north-hero', ST_GeogFromText('SRID=4326;POINT(-73.2257 44.8351)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://campabnaki.org/summer-camp-options/day-camp/','https://geocoding.geo.census.gov/geocoder/locations/address?street=1252+Abnaki+Road&city=North+Hero&state=VT&benchmark=Public_AR_Current&format=json']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Lochearn for Girls', NULL, 'https://www.camplochearn.com', 'https://www.camplochearn.com/apply.php', 'fun@camplochearn.com', '802-333-4211', '1061 Robinson Hill Road, PO Box 44', 'Post Mills', 'VT', '05058', 'Vermont', 'sleepaway', NULL, NULL, ARRAY['Horseback riding (English, optional add-on)','Swimming','Sailing','Canoeing','Kayaking','Paddleboarding','Waterskiing','Wakeboarding','Archery','Tennis','Soccer','Lacrosse','Field hockey','Gymnastics','Arts and crafts','Ceramics','Drama','Dance','Musical theatre','Climbing','Outdoor adventure','Culinary arts','Leadership training (ages 15-16)']::text[], 'girls', 7, 15, NULL, NULL, 'An overnight summer camp for girls ages 7 to 15 on Lake Fairlee in Post Mills, Vermont, founded in 1916. It offers two full sessions of about three and a half weeks, plus shorter "Middler" sessions of about two weeks for girls who have finished 4th grade or younger.', NULL, NULL, 6225, 10200, NULL, NULL, NULL, TRUE, TRUE, NULL, 'Payment terms: $2,500 deposit with application, $2,500 due by February 1, balance due by April 1. The page states no refund policy.', NULL, NULL, TRUE, 'https://www.camplochearn.com/about-lochearn/faqs.php', 2027, '6c2d7202-ccf2-5e58-a4be-372c92e53b25', 'camp-lochearn-for-girls-post-mills', ST_GeogFromText('SRID=4326;POINT(-72.2495 43.8367)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.camplochearn.com/about-lochearn/camp-activities.php','https://www.camplochearn.com/about-lochearn/dates-fees.php','https://www.camplochearn.com/about-lochearn/faqs.php','https://www.camplochearn.com/apply.php']::text[], '2026-11-13', '2026-11-13', TRUE),
('Capital Kids Summer Day Camp', 'Montpelier Recreation (City of Montpelier Community Services Department)', 'https://montpelier-vt.org/843/Capital-Kids-Day-Camp', 'https://vtmontpelierweb.myvscloud.com/webtrac/web/', NULL, '(802) 225-8699', 'Montpelier Recreation Area, Elm St.', 'Montpelier', 'VT', '05602', 'Vermont', 'day', ARRAY['arts','sports','nature','STEM']::text[], NULL, ARRAY['arts & crafts','games & sports','STEAM projects','team building','swimming (daily pool trips)','nature hikes','field trips','specialty workshops','circus skills']::text[], NULL, 6, 12, 1, 6, 'City-run licensed day camp for grades 1-6 (ages 6-12) at the Montpelier Recreation Area, running eight one-week themed sessions, 7:45am to 4:45pm, with arts and crafts, games and sports, STEAM projects and daily pool trips. Thursdays have a field trip or a specialty workshop.', NULL, NULL, 100, 225, 175, 'week', NULL, NULL, NULL, TRUE, 'You must submit the Cancellation Form to the Rec Center before June 12 to get a refund, minus a $50 administrative fee. Cancellations after June 12 get a 50% refund. If you book more than two weeks, you pay two weeks up front, half the balance by April 17 and the rest by June 12. Campers whose balance isn''t paid by June 12 are taken off the roster.', NULL, 'Daily trips to the Montpelier city pool are included in the registration fee.', NULL, NULL, 2026, '5411292d-f933-560b-b23f-0ccf60930974', 'capital-kids-summer-day-camp-montpelier', ST_GeogFromText('SRID=4326;POINT(-72.5715 44.2664)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://montpelier-vt.org/843/Capital-Kids-Day-Camp','https://montpelier-vt.org/Directory.aspx?DID=29']::text[], '2026-11-13', '2026-11-13', TRUE),
('Lost Nation Theater Intermediate Camps', 'Lost Nation Theater', 'https://lostnationtheater.org/intermediate-camps/', 'https://lostnationtheater.org/intermediate-camps/education-program-registration-form/', NULL, '(802) 229-0492', '39 Main Street', 'Montpelier', 'VT', '05602', 'Vermont', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['Musical theater','Theater','Comedy','Stage combat','Storytelling','Dance-theater','Public performances']::text[], NULL, 9, 18, NULL, NULL, 'One-week, full-day theater camps for ages 9 and up with some prior experience, run by Lost Nation Theater at Montpelier City Hall. Summer 2027 is a musical theater production intensive, Annie (kids), ending in four public performances.', NULL, NULL, 625, 625, NULL, NULL, NULL, NULL, NULL, TRUE, 'All sales final. A 50% non-refundable deposit is required, and the balance is due two weeks before the first day. No refunds once classes begin. Before the start date, partial refunds may be available on a time-based sliding scale.', NULL, NULL, NULL, NULL, 2027, '8a31ac6e-4cb8-5b2f-9b2f-16bed0729670', 'lost-nation-theater-intermediate-camps-montpelier', ST_GeogFromText('SRID=4326;POINT(-72.5715 44.2664)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://lostnationtheater.org/intermediate-camps/','https://lostnationtheater.org/intermediate-camps/2027-summer-musical-theater-production-intensive-annie-kids/']::text[], '2026-11-13', '2026-11-13', TRUE),
('North Branch Nature Center Summer Camps', 'North Branch Nature Center', 'https://northbranchnaturecenter.org/youth-programs/camps', NULL, NULL, '802-229-6206', '713 Elm Street', 'Montpelier', 'VT', '05602', 'Vermont', 'day', ARRAY['nature']::text[], NULL, ARRAY['Nature exploration','Loose parts play','Nature Museum','Arts and crafts','Tag games','Stories','Sit spots','Songs and circles']::text[], NULL, NULL, NULL, NULL, 7, 'Nature-based outdoor day camps run by Teacher-Naturalists for children in PreK through 7th grade, held at North Branch Nature Center in Montpelier. Campers spend their days outside exploring, playing games, hearing stories and doing crafts.', NULL, NULL, 310, 485, NULL, 'session', TRUE, TRUE, NULL, TRUE, '2026 policy: cancel by March 31 for a refund minus a $20 fee. Cancel April 1–May 31 for a refund minus a $50 fee. No refunds on or after June 1, though emergency exceptions may be granted. No partial refunds for missed days. Full refund if NBNC cancels the camp.', NULL, NULL, NULL, NULL, 2026, 'c42b48a1-687d-5560-9cf0-a4750d352a1d', 'north-branch-nature-center-summer-camps-montpelier', ST_GeogFromText('SRID=4326;POINT(-72.5715 44.2664)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://north-branch-nature-center.jumbula.com/CampBranchOUT2026/CampBranchOUT2026','https://north-branch-nature-center.jumbula.com/SummerCamp2026/AnimalEngineers','https://northbranchnaturecenter.org/youth-programs/camps']::text[], '2026-11-13', '2026-11-13', TRUE),
('Shelburne Parks and Recreation Summer Camps', 'Shelburne Parks and Recreation', 'https://www.shelburnevt.org/160/Parks-Recreation', NULL, NULL, '802-985-9551', NULL, 'Shelburne', 'VT', '05482', 'Vermont', 'day', ARRAY['sports','STEM']::text[], NULL, ARRAY['Tennis','Baseball','Rocketry','Soccer','Field hockey','Basketball','Ultimate frisbee','Dinosaur science','STEAM']::text[], NULL, 4, NULL, 0, 12, 'A town recreation program of week-long, half-day camps, each focused on one activity, such as tennis, baseball, soccer, rocketry or STEAM. Ages and grades depend on the camp, from age 4 up to entering 12th grade.', NULL, NULL, 175, 340, NULL, 'week', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, 'ed2a3f68-1dca-51c2-a32a-1a7e6e09ca29', 'shelburne-parks-and-recreation-summer-camps-shelburne', ST_GeogFromText('SRID=4326;POINT(-73.2435 44.3893)'), TRUE, FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.shelburnevt.org/160/Parks-Recreation','https://www.shelburnevt.org/DocumentCenter/View/7592/2026-summer-camp-overview']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Day Camps at Vermont Commons', 'Vermont Commons School', 'https://www.vermontcommons.org/summer-day-camps', 'https://www.homeroom.com/sites/vermont-commons-school-south-burlington/summer-2026/summer-day-camps/', NULL, '1-802-865-8084', '75 Green Mountain Drive', 'South Burlington', 'VT', '05403', 'Vermont', 'day', ARRAY['arts','STEM','nature']::text[], NULL, ARRAY['Clay sculpture','Chain reaction machines','Cardboard arcade games','Cardboard car races','Cooking','Food-related art projects','Creative writing','Nature exploration in the woods','Games']::text[], NULL, 8, 11, NULL, NULL, 'One-week themed day camp sessions for ages 8-11 at Vermont Commons School, built around hands-on projects like cardboard building, cooking and nature study, plus summer games.', NULL, NULL, 300, 375, 375, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '8a45bcb3-404a-5555-82b8-b0ec4b441894', 'summer-day-camps-at-vermont-commons-south-burlington', ST_GeogFromText('SRID=4326;POINT(-73.1826 44.4365)'), TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://www.vermontcommons.org/summer-day-camps']::text[], '2026-11-13', '2026-11-13', TRUE)
